'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['drawRoute']);
const { drawRoute } = api;

assert.deepStrictEqual(drawRoute(1, 1, []), ['.']);
assert.deepStrictEqual(drawRoute(4, 3, []), ['....', '....', '....']);
assert.deepStrictEqual(drawRoute(5, 3, [
  { x: 0, y: 0 },
  { x: 4, y: 0 },
  { x: 2, y: 1 },
  { x: 4, y: 2 },
  { x: 2, y: 1 }
]), ['#...#', '..#..', '....#']);
assert.deepStrictEqual(drawRoute(7, 2, [{ x: 6, y: 1 }]), ['.......', '......#']);

const points = [{ x: 1, y: 0 }, { x: 0, y: 1 }];
const before = points.map((point) => ({ ...point }));
const output = drawRoute(2, 2, points);
assert.deepStrictEqual(output, ['.#', '#.']);
assert.deepStrictEqual(points, before);
assert.notStrictEqual(output, points);

for (const width of [0, -1, 1001, 1.5, NaN, Infinity, '2']) {
  assert.throws(() => drawRoute(width, 2, []), TypeError);
}
for (const height of [0, -1, 1001, 1.5, NaN, Infinity, null]) {
  assert.throws(() => drawRoute(2, height, []), TypeError);
}
for (const badPoints of [null, {}, 'points']) {
  assert.throws(() => drawRoute(2, 2, badPoints), TypeError);
}
for (const point of [null, [], new Date(), {}, { x: 0 }, { y: 0 }, { x: -1, y: 0 }, { x: 5, y: 0 }, { x: 0, y: 2 }, { x: 1.5, y: 0 }, { x: 0, y: NaN }, { x: '0', y: 0 }]) {
  assert.throws(() => drawRoute(5, 2, [point]), TypeError);
}
const sparse = new Array(1);
assert.throws(() => drawRoute(2, 2, sparse), TypeError);
assert.throws(() => drawRoute(2, 2, [{ x: 0, y: 0 }, { x: 2, y: 1 }]), TypeError);

